import { createReadStream, createWriteStream } from 'node:fs';
import { copyFile, mkdir, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { pipeline } from 'node:stream/promises';
import { env } from '../../config/env.js';

// Where finished backup files live. Backups are written to a temporary file
// first and handed to a provider; the provider is the only thing that knows
// where they really are. Keys are generated by the server (never taken from a
// request), so nothing here can be steered outside the backup location.

const SAFE_KEY = /^[A-Za-z0-9._-]{8,200}$/;
function assertKey(key) {
  if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('Invalid backup storage key.');
}

export class LocalBackupStorage {
  constructor(dir) {
    this.dir = path.resolve(dir);
    this.name = 'local';
  }

  resolve(key) {
    assertKey(key);
    return path.join(this.dir, key);
  }

  async put(key, localPath) {
    await mkdir(this.dir, { recursive: true });
    await copyFile(localPath, this.resolve(key));
  }

  async size(key) {
    return (await stat(this.resolve(key))).size;
  }

  async exists(key) {
    try { await stat(this.resolve(key)); return true; } catch { return false; }
  }

  async getStream(key) {
    return createReadStream(this.resolve(key));
  }

  async download(key, localPath) {
    await pipeline(createReadStream(this.resolve(key)), createWriteStream(localPath));
  }

  async delete(key) {
    await rm(this.resolve(key), { force: true });
  }
}

export class S3BackupStorage {
  constructor() {
    this.name = 's3';
    this.bucket = env.S3_BUCKET;
    this.clientPromise = null;
  }

  async client() {
    if (!this.clientPromise) {
      this.clientPromise = import('@aws-sdk/client-s3').then((sdk) => ({
        sdk,
        s3: new sdk.S3Client({
          region: env.S3_REGION,
          endpoint: env.S3_ENDPOINT,
          forcePathStyle: Boolean(env.S3_ENDPOINT),
          credentials: { accessKeyId: env.S3_ACCESS_KEY_ID, secretAccessKey: env.S3_SECRET_ACCESS_KEY },
        }),
      }));
    }
    return this.clientPromise;
  }

  async put(key, localPath) {
    assertKey(key);
    const { sdk, s3 } = await this.client();
    const { size } = await stat(localPath);
    await s3.send(new sdk.PutObjectCommand({
      Bucket: this.bucket, Key: key, Body: createReadStream(localPath), ContentLength: size,
      ContentType: 'application/octet-stream', ServerSideEncryption: undefined,
    }));
  }

  async size(key) {
    assertKey(key);
    const { sdk, s3 } = await this.client();
    const head = await s3.send(new sdk.HeadObjectCommand({ Bucket: this.bucket, Key: key }));
    return Number(head.ContentLength);
  }

  async exists(key) {
    try { await this.size(key); return true; } catch { return false; }
  }

  async getStream(key) {
    assertKey(key);
    const { sdk, s3 } = await this.client();
    const res = await s3.send(new sdk.GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return res.Body;
  }

  async download(key, localPath) {
    await pipeline(await this.getStream(key), createWriteStream(localPath));
  }

  async delete(key) {
    assertKey(key);
    const { sdk, s3 } = await this.client();
    await s3.send(new sdk.DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }
}

let provider;
export function getBackupStorage() {
  if (!provider) {
    if (env.BACKUP_STORAGE === 's3') {
      if (!env.S3_BUCKET || !env.S3_ACCESS_KEY_ID || !env.S3_SECRET_ACCESS_KEY) {
        throw new Error('BACKUP_STORAGE=s3 needs S3_BUCKET, S3_ACCESS_KEY_ID and S3_SECRET_ACCESS_KEY.');
      }
      provider = new S3BackupStorage();
    } else {
      provider = new LocalBackupStorage(env.BACKUP_LOCAL_DIR);
    }
  }
  return provider;
}

// Tests swap in a throwaway location.
export function setBackupStorageForTests(p) {
  provider = p;
}
